ng // e.g. \"Size 42 / Black\" or \"100ml / EDP\"\n  sku      String // Unique Variant SKU e.g. \"NK-AF1-BLK-42\"\n  barcode  String? // Variant-specific barcode for laser scanners\n  imageUrl String? // Variant-specific photo/swatch\n\n  costPrice       Decimal @default(0)\n  price           Decimal // Specific variant selling price in ₦\n  quantity        Int     @default(0) // Specific variant stock count\n  minimumQuantity Int     @default(5) // Low stock threshold\n  isActive        Boolean @default(true)\n\n  attributes Json? // e.g. { \"Size\": \"42\", \"Color\": \"Black\" }\n\n  saleItems      SaleItem[]\n  stockMovements StockMovement[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([productId, sku])\n  @@index([productId])\n  @@index([barcode])\n  @@map(\"product_variants\")\n}\n\nmodel Brand {\n  id        String    @id @default(cuid())\n  tenantId  String\n  tenant    Tenant    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  name      String\n  imageUrl  String?\n  publicId  String?\n  slug      String\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@unique([tenantId, slug])\n  @@map(\"brands\")\n}\n\nmodel Category {\n  id        String     @id @default(cuid())\n  tenantId  String\n  tenant    Tenant     @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  name      String\n  slug      String\n  parentId  String?\n  parent    Category?  @relation(\"SubCategories\", fields: [parentId], references: [id], onDelete: Cascade)\n  children  Category[] @relation(\"SubCategories\")\n  products  Product[]\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  @@unique([tenantId, slug])\n  @@map(\"categories\")\n}\n\nmodel ProductImage {\n  id        String   @id @default(cuid())\n  productId String\n  publicId  String\n  imageUrl  String\n  isMain    Boolean  @default(false)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"product_images\")\n}\n\nmodel StockMovement {\n  id             String            @id @default(cuid())\n  tenantId       String\n  tenant         Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  storeId        String?\n  store          Store?            @relation(fields: [storeId], references: [id], onDelete: SetNull)\n  productId      String\n  product        Product           @relation(fields: [productId], references: [id], onDelete: Cascade)\n  variantId      String?\n  variant        ProductVariant?   @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User              @relation(fields: [userId], references: [id])\n  type           StockMovementType // PURCHASE, SALE, RETURN, ADJUSTMENT, BREAK_BULK\n  quantityChange Int // Positive or negative\n  reason         String? // e.g. \"Carton opened for piece sales\", \"Damaged goods\"\n  createdAt      DateTime          @default(now())\n\n  @@map(\"stock_movements\")\n}\n\n// -------------------------------------------------------------\n// 5. Sales, POS Checkout, Split Payments & Cash Balance\n// -------------------------------------------------------------\n\nmodel Sales {\n  id                String           @id @default(cuid())\n  invoiceNo         String           @unique // e.g. \"INV-2026-0001\"\n  tenantId          String\n  tenant            Tenant           @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  storeId           String?\n  store             Store?           @relation(fields: [storeId], references: [id], onDelete: SetNull)\n  registerSessionId String?\n  registerSession   RegisterSession? @relation(fields: [registerSessionId], references: [id], onDelete: SetNull)\n  cashierId         String\n  cashier           User             @relation(fie